mapper.select:
select apt.ai_prompt_template_id as aiPromptTemplateId, apt.template_scope as templateScope, apt.test_project_id as testProjectId, apt.session_scene as sessionScene, apt.template_title as templateTitle, apt.template_description as templateDescription, apt.template_content as templateContent, apt.builtin_status as builtinStatus, apt.enable_status as enableStatus, apt.sort_num as sortNum, apt.remark as remark, apt.del_status as delStatus, apt.create_time as createTime, apt.update_time as updateTime from ai_prompt_template apt where apt.del_status = 0
and apt.template_scope = #{templateScope}
and apt.test_project_id = #{testProjectId}
and apt.session_scene = #{sessionScene}
and apt.template_title like concat('%', #{templateTitle}, '%')
and apt.builtin_status = #{builtinStatus}
and apt.enable_status = #{enableStatus}
order by apt.template_scope asc, apt.sort_num asc, apt.ai_prompt_template_id asc

select count(1)
from ai_prompt_template apt
where apt.del_status = 0

    and apt.template_scope = #{templateScope}


    and apt.test_project_id = #{testProjectId}


    and apt.session_scene = #{sessionScene}


    and apt.template_title like concat('%', #{templateTitle}, '%')


    and apt.builtin_status = #{builtinStatus}


    and apt.enable_status = #{enableStatus}

select apt.ai_prompt_template_id, apt.template_scope, apt.test_project_id, apt.session_scene, apt.template_title, apt.template_description, apt.template_content, apt.builtin_status, apt.enable_status, apt.sort_num, apt.remark, apt.del_status, apt.create_time, apt.update_time from ai_prompt_template apt where apt.del_status = 0
and apt.template_scope = #{templateScope}
and apt.test_project_id = #{testProjectId}
and apt.session_scene = #{sessionScene}
and apt.template_title like concat('%', #{templateTitle}, '%')
and apt.builtin_status = #{builtinStatus}
and apt.enable_status = #{enableStatus}
order by apt.ai_prompt_template_id desc limit 1
